using System.Collections.Generic;
namespace Tally.Billing
{
    public static class RefundQueue
    {
        // connascence: accept - single-instance by design until the queue moves to the database
        public static List<string> Pending = new List<string>();
    }

    public class Refunds
    {
        public void Request(string invoiceId) { RefundQueue.Pending.Add(invoiceId); }
    }
}

namespace Tally.Api
{
    public class RefundsController
    {
        public int Waiting() => Tally.Billing.RefundQueue.Pending.Count;
    }
}

namespace Tally.Api
{
    public class RefundAdmin
    {
        public void Drop(string id) { Tally.Billing.RefundQueue.Pending.Remove(id); }
        public bool Has(string id) => Tally.Billing.RefundQueue.Pending.Contains(id);
        public void Reset() { Tally.Billing.RefundQueue.Pending.Clear(); }
    }

    public class RefundReport
    {
        public string Summary() => Tally.Billing.RefundQueue.Pending.Count + " waiting";
    }
}
